// Small helpers the screens render with: escaping, the colour swatches, the terms. The screens are
// a tool, not prose (ruled 2026-09-06): every word here is a label, a term or a verb. The one
// sentence on a screen is the FX's own, generated by core/fx.js.
// No Foundry here; strings in, strings out.
import { LAYER_WORDS } from '../core/corpus.js';

export const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

/** the term for where an FX lives: House · Stock (the two files; there is no draft layer, 2026-09-12) */
export const SOURCE_TAG = LAYER_WORDS;

/** the status of an ability, for the dot and the term: custom | stock | none | off */
export function statusOf({ fx, source, off }) {
  if (off) return 'off';
  if (!fx) return 'none';
  return source === 'stock' ? 'stock' : 'custom';
}
export const STATUS_WORDS = { custom: 'Custom', stock: 'Stock', none: 'No FX', off: 'Off' };


/** the kind of an ability, as a tag */
export const KIND_WORDS = { spell: 'Spell', weapon: 'Weapon', natural: 'Natural', feature: 'Feature', item: 'Item', effect: 'Effect', event: 'Event' };

/** the same kinds as a facet on the FX tab: what a list of them is called */
export const KIND_PLURAL = { spell: 'Spells', weapon: 'Weapons', natural: 'Natural', feature: 'Features', item: 'Items', effect: 'Effects', event: 'Events' };

export const dot = (status) => `<span class="dot ${status}"></span>`;

/** the title words for an FX id: "sharran-step" → "Sharran Step" */
export const idWords = (id) => String(id ?? '').replace(/^starter:/, '').replace(/-/g, ' ').replace(/\b[a-z]/g, (c) => c.toUpperCase());

/** the ten moment words of core/moments.js WHEN, each as a pill's term: dnd5e's two, then By the Books' eight */
export const MOMENT_TERMS = { use: 'Use', effect: 'Effect', maneuver: 'Maneuver', sneak: 'Sneak', fold: 'Fold', rider: 'Rider', 'hold-answered': 'Held roll', summon: 'Summon', unsummon: 'Unsummon', gift: 'Gift' };
